COMMENT ON COLUMN CITY.ID IS 'the unique identifier of the city';
COMMENT ON COLUMN CITY.CITY_NAME IS 'the name of the city';
COMMENT ON COLUMN COMPETITOR_EVENT.EVENT_ID IS 'the id of the eventMaps to event(id)';
COMMENT ON COLUMN COMPETITOR_EVENT.COMPETITOR_ID IS 'the id of the competitorMaps to games_competitor(id)';
ALTER TABLE COMPETITOR_EVENT MODIFY (COMPETITOR_ID ANNOTATIONS (ADD value_description 'commonsense evidence:The number of competitors who participated in a specific event could be calculated by grouping by event_id.'));
COMMENT ON COLUMN COMPETITOR_EVENT.MEDAL_ID IS 'the id of the medalMaps to medal(id)';
ALTER TABLE COMPETITOR_EVENT MODIFY (MEDAL_ID ANNOTATIONS (ADD value_description 'commonsense evidence:For a specific event, the competitor whose medal_id = 1 is the champion, the competitor whose medal_id = 2 is the runner-up, and the competitor whose medal_id = 3 got third place.'));
COMMENT ON COLUMN "EVENT".ID IS 'the unique identifier of the event';
COMMENT ON COLUMN "EVENT".SPORT_ID IS 'the id of the sportMaps to sport(id)';
ALTER TABLE "EVENT" MODIFY (SPORT_ID ANNOTATIONS (ADD value_description 'commonsense evidence:There may be different events for the same sport in Olympics.'));
COMMENT ON COLUMN "EVENT".EVENT_NAME IS 'the name of the event';
COMMENT ON COLUMN GAMES.ID IS 'the unique identifier of the game';
COMMENT ON COLUMN GAMES.GAMES_YEAR IS 'the year of the game';
COMMENT ON COLUMN GAMES.GAMES_NAME IS 'the name of the game';
ALTER TABLE GAMES MODIFY (GAMES_NAME ANNOTATIONS (ADD value_description 'commonsense evidence:games_name is ''games_year season'''));
COMMENT ON COLUMN GAMES.SEASON IS 'the season of the game';
ALTER TABLE GAMES MODIFY (SEASON ANNOTATIONS (ADD value_description 'commonsense evidence:The Olympics are held every four years and include both summer and winter games. The summer games include a wide range of sports, such as athletics, swimming, and gymnastics, while the winter games feature sports that are played on ice or snow, such as ice hockey, figure skating, and skiing.'));
COMMENT ON COLUMN GAMES_CITY.GAMES_ID IS 'the id of the gameMaps to games(id)';
COMMENT ON COLUMN GAMES_CITY.CITY_ID IS 'the id of the city that held the gameMaps to city(id)';
COMMENT ON COLUMN GAMES_COMPETITOR.ID IS 'the unique identifier of the record';
COMMENT ON COLUMN GAMES_COMPETITOR.GAMES_ID IS 'the id of the gameMaps to games(id)';
COMMENT ON COLUMN GAMES_COMPETITOR.PERSON_ID IS 'the id of the personMaps to person(id)';
ALTER TABLE GAMES_COMPETITOR MODIFY (PERSON_ID ANNOTATIONS (ADD value_description 'commonsense evidence:The times a person participated in the Olympics games could be calculated by grouping by person_id.'));
COMMENT ON COLUMN GAMES_COMPETITOR.AGE IS 'the age of the person when he/she participated in the game';
ALTER TABLE GAMES_COMPETITOR MODIFY (AGE ANNOTATIONS (ADD value_description 'commonsense evidence:If person A''s age was 22 when he participated in game A and his age was 24 when he participated in game B, it means that game A was held two years earlier than game B.'));
COMMENT ON COLUMN MEDAL.ID IS 'the unique identifier of the metal';
COMMENT ON COLUMN MEDAL.MEDAL_NAME IS 'the name of the medal';
COMMENT ON COLUMN NOC_REGION.ID IS 'the unique identifier of the noc region';
COMMENT ON COLUMN NOC_REGION.NOC IS 'the NOC code of the region';
ALTER TABLE NOC_REGION MODIFY (NOC ANNOTATIONS (ADD value_description 'commonsense evidence:A NOC code is a number used by the International Olympic Committee (IOC) to identify each of the national Olympic committees (NOCs) from around the world.'));
COMMENT ON COLUMN NOC_REGION.REGION_NAME IS 'the name of the region';
COMMENT ON COLUMN PERSON.ID IS 'the unique identifier of the person';
COMMENT ON COLUMN PERSON.FULL_NAME IS 'the full name of the person';
ALTER TABLE PERSON MODIFY (FULL_NAME ANNOTATIONS (ADD value_description 'commonsense evidence:A person''s full name is the complete name that they are known by, which typically includes their first name, middle name (if applicable), and last name.'));
COMMENT ON COLUMN PERSON.GENDER IS 'the gender of the person';
ALTER TABLE PERSON MODIFY (GENDER ANNOTATIONS (ADD value_description 'commonsense evidence:M stands for male and F stands for female.'));
COMMENT ON COLUMN PERSON.HEIGHT IS 'the height of the person';
COMMENT ON COLUMN PERSON.WEIGHT IS 'the weight of the person';
ALTER TABLE PERSON MODIFY (WEIGHT ANNOTATIONS (ADD value_description 'commonsense evidence:The unit of height is cm, and the unit of weight is kg. If the height or the weight of the person is 0, it means his/her height or weight is missing.'));
COMMENT ON COLUMN PERSON_REGION.PERSON_ID IS 'the id of the personMaps to person(id)';
COMMENT ON COLUMN PERSON_REGION.REGION_ID IS 'the id of the noc regionMaps to noc_region(id)';
